// server/attest.ts
var net = getNetwork("testnet");
var REST = net.endpoints.rest;
var EVM_RPC = "https://evm-testnet.qore.host";
var PQC_KEY_STATUS = "0x0000000000000000000000000000000000000a02";
var KEY_STATUS_ABI = [
  {
    type: "function",
    name: "pqcKeyStatus",
    stateMutability: "view",
    inputs: [{ name: "account", type: "address" }],
    outputs: [
      { name: "registered", type: "bool" },
      { name: "algorithmId", type: "uint8" },
      { name: "pubkey", type: "bytes" },
      { name: "extra", type: "uint256" }
    ]
  }
];
var diana = defineChain({
  id: 9800,
  name: "QoreChain Testnet",
  nativeCurrency: { name: "QOR", symbol: "QOR", decimals: 18 },
  rpcUrls: { default: { http: [EVM_RPC] } }
});
var pub = createPublicClient({ chain: diana, transport: http(EVM_RPC) });
async function accountSequence(address) {
  const res = await fetch(`${REST}/cosmos/auth/v1beta1/accounts/${address}`);
  const body = await res.json();
  const acc = body.account?.base_account ?? body.account ?? {};
  return { accountNumber: BigInt(acc.account_number ?? "0"), sequence: BigInt(acc.sequence ?? "0") };
}
var limiter = createRateLimiter(5);
var json = (status, body) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });
async function POST(request) {
  const mnemonic = process.env.QORE_ATTESTER_MNEMONIC?.trim();
  if (!mnemonic) return json(503, { error: "Attester not configured on this deployment.", code: "no-attester" });
  const ip = (request.headers.get("x-forwarded-for") ?? "unknown").split(",")[0].trim();
  if (limiter.limited(ip)) return json(429, { error: "Too many requests \u2014 try again later.", code: "rate-limited" });
  let txHash = "";
  try {
    txHash = String((await request.json()).txHash ?? "");
  } catch {
    return json(400, { error: "Body must be JSON { txHash }.", code: "bad-body" });
  }
  const acc = await deriveUnifiedAccount(mnemonic, 0);
  const pk = String(acc.privateKey);
  const evmAccount = privateKeyToAccount(pk.startsWith("0x") ? pk : `0x${pk}`);
  const wallet = createWalletClient({ chain: diana, account: evmAccount, transport: http(EVM_RPC) });
  const result = await attestFromNativeTx(txHash, {
    rest: REST,
    fetchJson: async (url) => {
      const r = await fetch(url);
      return { status: r.status, body: r.ok ? await r.json() : null };
    },
    hasPass: async (holder) => await pub.readContract({ address: QUANTUM_PASS_ADDRESS, abi: QUANTUM_PASS_ABI, functionName: "balanceOf", args: [holder] }) > 0n,
    proofUsed: async (h) => pub.readContract({ address: QUANTUM_PASS_ADDRESS, abi: QUANTUM_PASS_ABI, functionName: "nativeTxUsed", args: [h] }),
    keyRegistered: async (holder) => (await pub.readContract({ address: PQC_KEY_STATUS, abi: KEY_STATUS_ABI, functionName: "pqcKeyStatus", args: [holder] }))[0],
    submit: async (a) => {
      let windowTxHash;
      const w = await evmWindowStatus({ rest: REST, address: acc.cosmos });
      if (!w.live || w.remainingTxs < 1n) {
        const { accountNumber, sequence } = await accountSequence(acc.cosmos);
        const signer = new EthNativeSigner(acc, { signMode: "hybrid", rest: REST });
        const client = await import_stargate2.StargateClient.connect(net.endpoints.rpc);
        try {
          const res = await signer.signAndBroadcast(client, {
            chainId: net.chainId,
            accountNumber,
            sequence,
            fee: { amount: [{ denom: "uqor", amount: "100000" }], gas: "800000" },
            messages: [openEvmWindowMsg({ sender: acc.cosmos, blocks: 300n, maxTxs: 2n, maxValue: 0n })]
          });
          if (res.code !== 0) throw new Error(`window open failed (code ${res.code})`);
          windowTxHash = res.transactionHash;
        } finally {
          client.disconnect();
        }
        await new Promise((r) => setTimeout(r, 6e3));
      }
      const hash3 = await wallet.writeContract({
        address: QUANTUM_PASS_ADDRESS,
        abi: QUANTUM_PASS_ABI,
        functionName: "attest",
        args: [a.holder, a.scanHash, a.scoreBucket, a.chainsMask, a.exposedUsdBucket, a.nativeTxHash],
        gas: 600000n
      });
      const rcpt = await pub.waitForTransactionReceipt({ hash: hash3, timeout: 6e4 });
      if (rcpt.status !== "success") throw new Error(`attest reverted: ${hash3}`);
      return { evmTxHash: hash3, windowTxHash };
    }
  }).catch((err) => ({ status: 502, body: { error: err instanceof Error ? err.message : String(err), code: "submit-failed" } }));
  return json(result.status, result.body);
}
export {
  POST
};
